mapper.select:
SELECT NOTI_SEQ AS noti_seq, NOTI_TYPE_CD AS noti_type_cd, TITLE AS title, TO_CHAR(START_DT, 'YYYY-MM-DD') AS start_dt, TO_CHAR(END_DT, 'YYYY-MM-DD') AS end_dt, NVL(PIN_YN, 'N') AS pin_yn, NVL(POPUP_YN, 'N') AS popup_yn, NVL(VIEW_CNT, 0) AS view_cnt, NVL(USE_YN, 'Y') AS use_yn, TO_CHAR(UPDATED_AT, 'YYYY-MM-DD HH24:MI:SS') AS updated_at, UPDATED_BY AS updated_by, TO_CHAR(CREATED_AT, 'YYYY-MM-DD HH24:MI:SS') AS created_at, CREATED_BY AS created_by FROM ADM_NOTI_MST WHERE 1=1
AND NVL(USE_YN, 'Y') = #{use_yn}
AND NVL(USE_YN, 'Y') = 'Y'
AND NOTI_TYPE_CD = #{noti_type_cd}
AND TITLE LIKE '%' || #{title} || '%'
ORDER BY NVL(PIN_YN, 'N') DESC, NVL(START_DT, DATE '1900-01-01') DESC, NOTI_SEQ DESC

mapper.update:
UPDATE ADM_NOTI_MST
   SET USE_YN = 'N',
       UPDATED_AT = SYSTIMESTAMP,
       UPDATED_BY = #{updated_by}
 WHERE NOTI_SEQ = #{noti_seq}
